/* DAWAH X — ahmad, অধ্যায় 45 · খণ্ড 45 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][45]=[[8801,8801,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَأْتِي ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏ ‏مِنْ قِبَلِ الْمَشْرِقِ وَهِمَّتُهُ ‏ ‏الْمَدِينَةُ ‏ ‏حَتَّى يَنْزِلَ دَائِرَ ‏ ‏أُحُدٍ ‏ ‏ثُمَّ تَصْرِفُ الْمَلَائِكَةُ وَجْهَهُ قِبَلَ ‏ ‏الشَّامِ ‏ ‏وَهُنَالِكَ يَهْلِكُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏كَذَا قَالَ أَبِي فِي هَذِهِ الْأَحَادِيثِ ‏","","",""],[8802,8802,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ دِينَارٍ يَعْنِي عَبْدَ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَى بُنْيَانًا فَأَحْسَنَهُ وَأَجْمَلَهُ إِلَّا مَوْضِعَ ‏ ‏لَبِنَةٍ ‏ ‏مِنْ زَاوِيَةٍ مِنْ زَوَايَاهُ فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ وَيَعْجَبُونَ لَهُ وَيَقُولُونَ هَلَّا وُضِعَتْ هَذِهِ ‏ ‏اللَّبِنَةُ ‏ ‏قَالَ فَأَنَا تِلْكَ ‏ ‏اللَّبِنَةُ ‏ ‏وَأَنَا خَاتَمُ النَّبِيِّينَ ‏","","",""],[8803,8803,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏عُتْبَةُ بْنُ مُسْلِمٍ ‏ ‏مَوْلَى ‏ ‏بَنِي تَمِيمٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏مَوْلَى ‏ ‏بَنِي زُرَيْقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ كُلَّهُ ثُمَّ لِيَطْرَحْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ شِفَاءً وَفِي الْآخَرِ دَاءً ‏","","",""],[8804,8804,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏","","",""],[8805,8805,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ الشَّيْطَانُ الْمُنَادِيَ يُنَادِي بِالصَّلَاةِ ‏ ‏وَلَّى ‏ ‏وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الصَّوْتَ فَإِذَا فَرَغَ رَجَعَ فَوَسْوَسَ فَإِذَا أَخَذَ فِي الْإِقَامَةِ فَعَلَ مِثْلَ ذَلِكَ ‏","","",""],[8806,8806,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَجِدُ مِنْ شِرَارِ النَّاسِ يَوْمَ الْقِيَامَةِ الَّذِي يَأْتِي هَؤُلَاءِ بِحَدِيثِ هَؤُلَاءِ وَهَؤُلَاءِ بِحَدِيثِ هَؤُلَاءِ ‏","","",""],[8807,8807,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَيُؤْمِنَ النَّاسُ أَجْمَعُونَ فَيَوْمَئِذٍ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏} ‏وَلَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا ‏ ‏الْيَهُودَ ‏ ‏فَيَفِرَّ الْيَهُودِيُّ وَرَاءَ الْحَجَرِ فَيَقُولَ الْحَجَرُ يَا عَبْدَ اللَّهِ يَا مُسْلِمُ هَذَا يَهُودِيٌّ وَرَائِي وَلَا تَقُومُ السَّاعَةُ حَتَّى تُقَاتِلُوا قَوْمًا نِعَالُهُمْ الشَّعَرُ ‏","","",""],[8808,8808,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏تَوَلَّى ‏ ‏قَوْمًا بِغَيْرِ إِذْنِ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏ ‏وَالْمَدِينَةُ ‏ ‏حَرَامٌ فَمَنْ ‏ ‏أَحْدَثَ ‏ ‏فِيهَا أَوْ ‏ ‏آوَى ‏ ‏مُحْدِثًا ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏ ‏وَذِمَّةُ ‏ ‏الْمُسْلِمِينَ وَاحِدَةٌ ‏ ‏يَسْعَى بِهَا ‏ ‏أَدْنَاهُمْ ‏ ‏فَمَنْ ‏ ‏أَخْفَرَ ‏ ‏مُسْلِمًا فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏عَدْلًا ‏ ‏وَلَا ‏ ‏صَرْفًا ‏","","",""],[8809,8809,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَكَّلَ اللَّهُ عَزَّ وَجَلَّ بِحِفْظِ امْرِئٍ خَرَجَ فِي سَبِيلِ اللَّهِ لَا يُخْرِجُهُ إِلَّا الْجِهَادُ فِي سَبِيلِ اللَّهِ وَتَصْدِيقٌ بِكَلِمَاتِ اللَّهِ حَتَّى يُوجِبَ لَهُ الْجَنَّةَ أَوْ يُرْجِعَهُ إِلَى بَيْتِهِ أَوْ مِنْ حَيْثُ خَرَجَ ‏","","",""],[8810,8810,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏كُلِمَ ‏ ‏فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَجِيءُ يَوْمَ الْقِيَامَةِ جُرْحُهُ كَهَيْئَتِهِ يَوْمَ جُرِحَ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏","","",""],[8811,8811,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْتَجَّ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏قَالَ فَقَالَ ‏ ‏مُوسَى ‏ ‏يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ ‏ ‏أَغْوَيْتَ ‏ ‏النَّاسَ وَأَخْرَجْتَهُمْ مِنْ الْجَنَّةِ قَالَ فَقَالَ ‏ ‏آدَمُ ‏ ‏أَنْتَ ‏ ‏مُوسَى ‏ ‏أَنْتَ ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِكَلَامِهِ تَلُومُنِي عَلَى عَمَلٍ أَعْمَلُهُ كَتَبَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ قَالَ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏","","",""],[8812,8812,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ يُكْنَى أَبَا الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي هَاشِمٍ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ عَزَّ وَجَلَّ لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا يَا ‏ ‏أُمَّ الزُّبَيْرِ عَمَّةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا سَلَانِي مِنْ مَالِي مَا شِئْتُمَا ‏","","",""],[8813,8813,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أُحِبُّ أَنَّ ‏ ‏أُحُدًا ‏ ‏ذَاكُمْ يُحَوَّلُ ذَهَبًا يَكُونُ عِنْدِي بَعْدَ ثَلَاثٍ مِنْهُ شَيْءٌ إِلَّا شَيْئًا ‏ ‏أَرْصُدُهُ ‏ ‏لِدَيْنٍ إِنَّ الْأَكْثَرِينَ هُمْ الْأَقَلُّونَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ قَالَ هَكَذَا وَهَكَذَا وَهَكَذَا وَهَكَذَا وَقَلِيلٌ مَا هُمْ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَبَيْنَ يَدَيْهِ وَوَرَاءَهُ ‏","","",""],[8814,8814,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي ‏ ‏أَوْ عَلَى الْمُؤْمِنِينَ ‏ ‏لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ وَهُوَ ابْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏فَذَكَرَ مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[8815,8815,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ الرَّجُلُ ‏ ‏مُخْتَصِرًا ‏","","",""],[8816,8816,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ اللَّيْلِ فَلْيَفْتَتِحْ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[8817,8817,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ قَبْلَ طُلُوعِ الشَّمْسِ سَجْدَةً فَقَدْ أَدْرَكَ الصَّلَاةَ وَمَنْ أَدْرَكَ قَبْلَ غُرُوبِ الشَّمْسِ سَجْدَةً فَقَدْ أَدْرَكَ الصَّلَاةَ ‏","","",""],[8818,8818,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسْلِمٌ يَعْنِي ابْنَ خَالِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ عَلَى أَخِيهِ الْمُسْلِمِ فَأَطْعَمَهُ طَعَامًا فَلْيَأْكُلْ مِنْ طَعَامِهِ وَلَا يَسْأَلْهُ عَنْهُ فَإِنْ سَقَاهُ شَرَابًا مِنْ شَرَابِهِ فَلْيَشْرَبْ مِنْ شَرَابِهِ وَلَا يَسْأَلْهُ عَنْهُ ‏","","",""],[8819,8819,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ ‏ ‏أَوْ مُرَّ ‏ ‏عَلَيْهِ بِجِنَازَةٍ سَأَلَهُمْ هَلْ تَرَكَ دَيْنًا فَإِنْ قَالُوا نَعَمْ قَالَ هَلْ تَرَكَ وَفَاءً فَإِنْ قَالُوا نَعَمْ صَلَّى عَلَيْهِ وَإِنْ قَالُوا لَا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ ‏","","",""],[8820,8820,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعَانِ فِي النَّارِ أَبَدًا اجْتِمَاعًا يَضُرُّ أَحَدَهُمَا قَالُوا مَنْ يَا رَسُولَ اللَّهِ قَالَ مُؤْمِنٌ يَقْتُلُهُ كَافِرٌ ثُمَّ ‏ ‏يُسَدَّدُ ‏ ‏بَعْدَ ذَلِكَ ‏","","",""],[8821,8821,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَضَمَّنَ اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا إِيمَانًا بِي وَتَصْدِيقًا بِرُسُلِي أَنْ أُدْخِلَهُ الْجَنَّةَ أَوْ أُرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ نَائِلًا مَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ ‏","","",""],[8822,8822,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يُجْرَحُ فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ يُجْرَحُ فِي سَبِيلِهِ إِلَّا لَقِيَ اللَّهَ عَزَّ وَجَلَّ كَهَيْئَتِهِ يَوْمَ جُرِحَ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا الْحَدِيثِ ‏","","",""],[8823,8823,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ يُعْرَضُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقُرْآنَ فِي كُلِّ سَنَةٍ مَرَّةً فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ عُرِضَ عَلَيْهِ مَرَّتَيْنِ ‏","","",""],[8824,8824,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنِيهِ ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ جُهِلَ عَلَيْهِ ‏ ‏فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[8825,8825,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا بِالصَّلَاةِ فَإِنَّ فَيْحَهَا مِنْ حَرِّ جَهَنَّمَ ‏","","",""],[8826,8826,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَسَّانَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُكْلَمُ ‏ ‏عَبْدٌ فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَجِيءُ جُرْحُهُ يَوْمَ الْقِيَامَةِ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ مِسْكٍ ‏","","",""],[8827,8827,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنْ كَانَ قَالَهُ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ الْوُضُوءِ ‏ ‏و قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَسْتَنُّ ‏ ‏قَبْلَ أَنْ أَنَامَ وَبَعْدَ مَا أَسْتَيْقِظُ وَقَبْلَ مَا آكُلُ وَبَعْدَ مَا آكُلُ حِينَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَا قَالَ ‏","","",""],[8828,8828,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ الْمُجْمِرِ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَقِيتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَلَى ظَهْرِ الْمَسْجِدِ وَعَلَيْهِ سَرَاوِيلُ مِنْ تَحْتِ قَمِيصِهِ فَنَزَعَ سَرَاوِيلَهُ ثُمَّ تَوَضَّأَ وَغَسَلَ وَجْهَهُ وَيَدَيْهِ وَرَفَعَ فِي عَضُدَيْهِ الْوُضُوءَ وَرِجْلَيْهِ فَرَفَعَ فِي سَاقَيْهِ ثُمَّ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أُمَّتِي يَأْتُونَ يَوْمَ الْقِيَامَةِ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ آثَارِ الْوُضُوءِ فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏","","",""],[8829,8829,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏خَتَنُ ‏ ‏سَلَمَةَ الْأَبْرَشِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمَنَّوْا لِقَاءَ الْعَدُوِّ فَإِنَّكُمْ لَا تَدْرُونَ مَا يَكُونُ فِي ذَلِكَ ‏","","",""],[8830,8830,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو صَخْرٍ حُمَيْدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ إِسْحَاقَ ‏ ‏مَوْلَى ‏ ‏زَائِدَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ وَرَمَضَانُ إِلَى رَمَضَانَ مُكَفِّرَاتٌ مَا بَيْنَهُنَّ مَا اجْتُنِبَتْ الْكَبَائِرُ ‏","","",""],[8831,8831,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ مُؤْلَفٌ وَلَا خَيْرَ فِيمَنْ لَا يَأْلَفُ وَلَا يُؤْلَفُ ‏","","",""],[8832,8832,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ قُرِئَ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَبْوَابَ الْجَنَّةِ تُفْتَحُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللَّهِ شَيْئًا إِلَّا رَجُلٌ بَيْنَهُ وَبَيْنَ أَخِيهِ ‏ ‏شَحْنَاءُ ‏ ‏فَيُقَالُ أَنْظِرُوهُمَا حَتَّى يَصْطَلِحَا مَرَّتَيْنِ ‏","","",""],[8833,8833,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ زَحْرٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَيُّهَا النَّاسُ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏فَرَضَ لَكُمْ عَلَى لِسَانِ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ فِي الْحَضَرِ أَرْبَعًا وَفِي السَّفَرِ رَكْعَتَيْنِ ‏","","",""],[8834,8834,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏صَالِحُ بْنُ أَبِي صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَتَحَمَّدَنَّ اللَّهُ يَوْمَ الْقِيَامَةِ عَلَى أُنَاسٍ مَا عَمِلُوا مِنْ خَيْرٍ قَطُّ فَيُخْرِجُهُمْ مِنْ النَّارِ بَعْدَمَا احْتَرَقُوا فَيُدْخِلُهُمْ الْجَنَّةَ بِرَحْمَتِهِ بَعْدَ شَفَاعَةِ مَنْ يَشْفَعُ ‏","","",""],[8835,8835,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالْقَانِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي ‏ ‏زُمْرَةٌ ‏ ‏هُمْ سَبْعُونَ أَلْفًا تُضِيءُ وُجُوهُهُمْ إِضَاءَةَ الْقَمَرِ لَيْلَةَ الْبَدْرِ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَقَامَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ الْأَسَدِيُّ ‏ ‏يَرْفَعُ ‏ ‏نَمِرَةً ‏ ‏عَلَيْهِ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ قَامَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ ‏ ‏أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ سَبَقَكَ ‏ ‏عُكَّاشَةُ ‏","","",""],[8836,8836,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَعَلِيِّ بْنِ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَبِيصَةُ بْنُ ذُؤَيْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُجْمَعَ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَبَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[8837,8837,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الرَّحْمَةِ وَغُلِّقَتْ أَبْوَابُ جَهَنَّمَ ‏ ‏وَسُلْسِلَتْ ‏ ‏الشَّيَاطِينُ ‏","","",""],[8838,8838,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فُلَانٍ الْخَثْعَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ سَفَرًا فَرَكِبَ ‏ ‏رَاحِلَتَهُ ‏ ‏قَالَ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ ‏ ‏وَالْخَلِيفَةُ ‏ ‏فِي الْأَهْلِ ‏ ‏قَالَ وَأُرَاهُ قَالَ وَالْحَامِلُ عَلَى الظَّهْرِ ‏ ‏اللَّهُمَّ اصْحَبْنَا بِنُصْحٍ وَاقْلِبْنَا ‏ ‏بِذِمَّةٍ ‏ ‏أَعُوذُ بِكَ مِنْ مِلْحِ ‏ ‏وَعْثَاءِ ‏ ‏السَّفَرِ ‏ ‏وَكَآبَةِ ‏ ‏الْمُنْقَلَبِ ‏","","",""],[8839,8839,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَجْلَحُ ‏ ‏أَنَّ ‏ ‏أَبَا بُرْدَةَ بْنَ أَبِي مُوسَى الْأَشْعَرِيَّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فِي الْجُمُعَةِ لَسَاعَةً مَا دَعَا اللَّهَ فِيهَا عَبْدٌ مُؤْمِنٌ بِشَيْءٍ إِلَّا اسْتَجَابَ اللَّهُ لَهُ ‏","","",""],[8840,8840,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ أُدْخِلَ الْجَنَّةَ وَفِيهِ أُخْرِجَ مِنْهَا ‏","","",""],[8841,8841,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَهِدَ الْجِنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ ‏ ‏وَقَالَ ‏ ‏عَتَّابٌ ‏ ‏حَتَّى تُفْرَغَ ‏ ‏فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏قِيلَ وَمَا ‏ ‏الْقِيرَاطَانِ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ ‏","","",""],[8842,8842,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏لَا يَصْبُغُونَ فَخَالِفُوهُمْ ‏","","",""],[8843,8843,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو إِدْرِيسَ الْخَوْلَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَلْيَنْثُرْ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[8844,8844,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ لَهِيعَةَ بْنِ عُقْبَةَ ‏ ‏وَعَنْ ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏لَهِيعَةَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَرْدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَإِيَّاكُمْ وَالْخَيْلَ ‏ ‏الْمُنَفِّلَةَ ‏ ‏فَإِنَّهَا إِنْ تَلْقَ تَفِرَّ وَإِنْ تَغْنَمْ ‏ ‏تَغْلُلْ ‏","","",""],[8845,8845,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ وَالْعَشْرَ الْأَوَاسِطَ فَمَاتَ حِينَ مَاتَ وَهُوَ ‏ ‏يَعْتَكِفُ ‏ ‏عِشْرِينَ يَوْمًا ‏","","",""],[8846,8846,"","","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏عَنْ ‏ ‏جَهْمِ بْنِ أَبِي الْجَهْمِ ‏ ‏عَنْ ‏ ‏مِسْوَرِ بْنِ مَخْرَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ جَعَلَ الْحَقَّ عَلَى لِسَانِ ‏ ‏عُمَرَ ‏ ‏وَقَلْبِهِ ‏","","",""],[8847,8847,"","","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ مِنْبَرِي وَبَيْتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏ ‏حَدَّثَنَا ‏ ‏نُوحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ إِلَّا أَنَّهُ قَالَ مِنْبَرِي ‏ ‏عَلَى تُرْعَةٍ مِنْ ‏ ‏تُرَعِ ‏ ‏الْجَنَّةِ ‏","","",""],[8848,8848,"","","‏ ‏حَدَّثَنَا ‏ ‏نُوحٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي الْعُمَرِيَّ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ يَرْجِعَ النَّاسُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏حَتَّى تَصِيرَ ‏ ‏مَسَالِحُهُمْ ‏ ‏بِسِلَاحٍ ‏","","",""],[8849,8849,"","","‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ مَيْمُونٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَكْعَتَيْ الضُّحَى ‏","","",""],[8850,8850,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا تَأْمُرُنِي قَالَ ‏ ‏بَرَّ ‏ ‏أُمَّكَ ثُمَّ عَادَ فَقَالَ ‏ ‏بَرَّ ‏ ‏أُمَّكَ ثُمَّ عَادَ الرَّابِعَةَ فَقَالَ ‏ ‏بَرَّ ‏ ‏أَبَاكَ ‏","","",""],[8851,8851,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُؤْمِنٍ يُشَاكُ بِشَوْكَةٍ فِي الدُّنْيَا ‏ ‏يَحْتَسِبُهَا ‏ ‏إِلَّا قُصِّرَ بِهَا مِنْ خَطَايَاهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[8852,8852,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّبَيْرُ بْنُ سَعِيدٍ ‏ ‏فَذَكَرَ حَدِيثًا عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏قَالَ وَحَدَّثَ ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏أَيْضًا ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ يُضْحِكُ بِهَا جُلَسَاءَهُ يَهْوِي بِهَا مِنْ أَبْعَدِ مِنْ ‏ ‏الثُّرَيَّا ‏","","",""],[8853,8853,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسُقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَا فِيمَا دُونَ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏","","",""],[8854,8854,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏التَّلَقِّي ‏ ‏وَأَنْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏","","",""],[8855,8855,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏مَا كَانَ عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[8856,8856,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالْقَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يَقُولُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْعَبْدِ الْمَمْلُوكِ الْمُصْلِحِ أَجْرَانِ ‏ ‏وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ لَوْلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ وَالْحَجُّ ‏ ‏وَبِرُّ ‏ ‏أُمِّي ‏ ‏لَأَحْبَبْتُ أَنْ أَمُوتَ وَأَنَا مَمْلُوكٌ ‏","","",""],[8857,8857,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏وَحِصْنٌ حَصِينٌ مِنْ النَّارِ ‏","","",""],[8858,8858,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِيسَى بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَرِيرُ بْنُ يَزِيدَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا زُرْعَةَ بْنَ عَمْرِو بْنِ جَرِيرٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدٌّ يُعْمَلُ فِي الْأَرْضِ خَيْرٌ لِأَهْلِ الْأَرْضِ مِنْ أَنْ يُمْطَرُوا ثَلَاثِينَ صَبَاحًا ‏","","",""],[8859,8859,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو ثِفَالٍ الْمُرِّيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَذَعُ ‏ ‏مِنْ الضَّأْنِ خَيْرٌ مِنْ السَّيِّدِ مِنْ الْمَعْزِ ‏ ‏قَالَ ‏ ‏دَاوُدُ ‏ ‏السَّيِّدُ الْجَلِيلُ ‏","","",""],[8860,8860,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ نَوْفَلٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ رَافِعٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الرَّمِيَّةِ ‏ ‏أَنْ ‏ ‏تُرْمَى الدَّابَّةُ ثُمَّ تُؤْكَلَ وَلَكِنْ تُذْبَحُ ثُمَّ ‏ ‏لْيَرْمُوا إِنْ شَاءُوا ‏","","",""],[8861,8861,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَرَصَتْ نَمْلَةٌ نَبِيًّا مِنْ الْأَنْبِيَاءِ فَأَمَرَ بِقَرْيَةِ النَّمْلِ فَأُحْرِقَتْ فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ فِي ‏ ‏أَنْ قَرَصَتْكَ نَمْلَةٌ أَهْلَكْتَ أُمَّةً مِنْ الْأُمَمِ تُسَبِّحُ ‏","","",""],[8862,8862,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ ثَوْبَانَ ‏ ‏أُرَاهُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ وَرْدَانَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لِرَجُلٍ تَعَالَ ‏ ‏أُوَدِّعْكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ كَمَا وَدَّعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَوْدَعْتُكَ اللَّهَ الَّذِي لَا يُضَيِّعُ وَدَائِعَهُ ‏","","",""],[8863,8863,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ بْنِ وَاقِدٍ الْحَرَّانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏وَالْمُغِيرَةِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا سَمِعْنَاهُ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ أَحَدٌ أَعْلَمَ بِحَدِيثِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي إِلَّا مَا كَانَ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَإِنَّهُ كَانَ يَكْتُبُ بِيَدِهِ ‏ ‏وَيَعِيهِ ‏ ‏بِقَلْبِهِ وَكُنْتُ ‏ ‏أَعِيهِ ‏ ‏بِقَلْبِي وَلَا أَكْتُبُ بِيَدِي ‏ ‏وَاسْتَأْذَنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْكِتَابِ عَنْهُ فَأَذِنَ لَهُ ‏","","",""],[8864,8864,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَيْسَ فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏صَدَقَةٌ ‏ ‏وَلَيْسَ فِيمَا دُونَ خَمْسِ ‏ ‏ذَوْدٍ ‏ ‏صَدَقَةٌ ‏","","",""],[8865,8865,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَلْجٍ يَحْيَى بْنُ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏أَنَّهُ حَدَّثَهُ قَالَ ‏ ‏قَالَ لِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُعَلِّمُكَ كَلِمَةً مِنْ كَنْزِ الْجَنَّةِ قَالَ قُلْتُ نَعَمْ فِدَاكَ أَبِي وَأُمِّي قَالَ قُلْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[8866,8866,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَنْعَمَ اللَّهُ عَلَى عَبْدٍ نِعْمَةً إِلَّا وَهُوَ يُحِبُّ أَنْ يَرَى أَثَرَهَا عَلَيْهِ ‏","","",""],[8867,8867,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِخِيَارِكُمْ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏خِيَارُكُمْ أَطْوَلُكُمْ أَعْمَارًا وَأَحْسَنُكُمْ أَخْلَاقًا ‏","","",""],[8868,8868,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُتَلَقَّى الْجَلَبُ ‏ ‏فَإِنْ ‏ ‏ابْتَاعَ ‏ ‏مُبْتَاعٌ ‏ ‏فَصَاحِبُ السِّلْعَةِ ‏ ‏بِالْخِيَارِ ‏ ‏إِذَا وَرَدَتْ السُّوقَ ‏","","",""],[8869,8869,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ اللُّؤْلُؤِيُّ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيَخْرُجَنَّ رِجَالٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏رَغْبَةً عَنْهَا ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ ‏","","",""],[8870,8870,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ ‏ ‏فَلْيُفْرِغْ ‏ ‏عَلَى يَدَيْهِ ثَلَاثَ مَرَّاتٍ قَبْلَ أَنْ يُدْخِلَهُمَا فِي الْإِنَاءِ فَإِنَّهُ لَا يَدْرِي فِيمَ بَاتَتْ يَدُهُ ‏","","",""],[8871,8871,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِي يَوْمِ الْجُمُعَةِ سَاعَةٌ لَا ‏ ‏يُوَافِقُهَا ‏ ‏عَبْدٌ مُسْلِمٌ إِلَّا اسْتُجِيبَ لَهُ ‏","","",""],[8872,8872,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ذَوَّادُ بْنُ عُلْبَةَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهَجِّرُ ‏ ‏قَالَ فَصَلَّيْتُ ثُمَّ جِئْتُ فَجَلَسْتُ إِلَيْهِ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏اشِكَمَتْ ‏ ‏دَرْدْ ‏ ‏قَالَ قُلْتُ لَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏صَلِّ فَإِنَّ فِي الصَّلَاةِ شِفَاءً ‏","","",""],[8873,8873,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكْذِبْ ‏ ‏إِبْرَاهِيمُ ‏ ‏إِلَّا ثَلَاثَ كَذِبَاتٍ قَوْلُهُ حِينَ دُعِيَ إِلَى آلِهَتِهِمْ ‏ { ‏إِنِّي ‏ ‏سَقِيمٌ ‏ } ‏وَقَوْلُهُ ‏ { ‏فَعَلَهُ كَبِيرُهُمْ هَذَا ‏} ‏وَقَوْلُهُ ‏ ‏لِسَارَةَ ‏ ‏إِنَّهَا أُخْتِي قَالَ وَدَخَلَ ‏ ‏إِبْرَاهِيمُ ‏ ‏قَرْيَةً فِيهَا مَلِكٌ مِنْ الْمُلُوكِ ‏ ‏أَوْ جَبَّارٌ مِنْ الْجَبَابِرَةِ ‏ ‏فَقِيلَ دَخَلَ ‏ ‏إِبْرَاهِيمُ ‏ ‏اللَّيْلَةَ بِامْرَأَةٍ مِنْ أَحْسَنِ النَّاسِ قَالَ فَأَرْسَلَ إِلَيْهِ الْمَلِكُ ‏ ‏أَوْ الْجَبَّارُ ‏ ‏مَنْ هَذِهِ مَعَكَ قَالَ أُخْتِي قَالَ أَرْسِلْ بِهَا قَالَ فَأَرْسَلَ بِهَا إِلَيْهِ وَقَالَ لَهَا لَا تُكَذِّبِي قَوْلِي فَإِنِّي قَدْ أَخْبَرْتُهُ أَنَّكِ أُخْتِي إِنْ عَلَى الْأَرْضِ مُؤْمِنٌ غَيْرِي وَغَيْرُكِ قَالَ فَلَمَّا دَخَلَتْ إِلَيْهِ قَامَ إِلَيْهَا قَالَ فَأَقْبَلَتْ تَوَضَّأُ وَتُصَلِّي وَتَقُولُ اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي آمَنْتُ بِكَ وَبِرَسُولِكَ وَأَحْصَنْتُ فَرْجِي إِلَّا عَلَى زَوْجِي فَلَا ‏ ‏تُسَلِّطْ ‏ ‏عَلَيَّ الْكَافِرَ قَالَ ‏ ‏فَغُطَّ ‏ ‏حَتَّى ‏ ‏رَكَضَ ‏ ‏بِرِجْلِهِ ‏ ‏قَالَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهَا قَالَتْ اللَّهُمَّ إِنَّهُ إِنْ يَمُتْ يُقَلْ هِيَ قَتَلَتْهُ قَالَ فَأُرْسِلَ ثُمَّ قَامَ إِلَيْهَا فَقَامَتْ تَوَضَّأُ وَتُصَلِّي وَتَقُولُ اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنِّي آمَنْتُ بِكَ وَبِرَسُولِكَ وَأَحْصَنْتُ فَرْجِي إِلَّا عَلَى زَوْجِي فَلَا تُسَلِّطْ عَلَيَّ الْكَافِرَ قَالَ ‏ ‏فَغُطَّ ‏ ‏حَتَّى ‏ ‏رَكَضَ ‏ ‏بِرِجْلِهِ ‏ ‏قَالَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهَا قَالَتْ اللَّهُمَّ إِنَّهُ إِنْ يَمُتْ يُقَلْ هِيَ قَتَلَتْهُ قَالَ فَأُرْسِلَ فَقَالَ فِي الثَّالِثَةِ ‏ ‏أَوْ الرَّابِعَةِ ‏ ‏مَا أَرْسَلْتُمْ إِلَيَّ إِلَّا شَيْطَانًا ارْجِعُوهَا إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَأَعْطُوهَا ‏ ‏هَاجَرَ ‏ ‏قَالَ فَرَجَعَتْ فَقَالَتْ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏أَشَعَرْتَ أَنَّ اللَّهَ عَزَّ وَجَلَّ رَدَّ كَيْدَ الْكَافِرِ وَأَخْدَمَ وَلِيدَةً ‏","","",""],[8874,8874,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ اللَّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ ‏ ‏مَرِضْتُ فَلَمْ ‏ ‏يَعُدْنِي ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَظَمِئْتُ فَلَمْ يَسْقِنِي ابْنُ ‏ ‏آدَمَ ‏ ‏فَقُلْتُ أَتَمْرَضُ يَا رَبِّ قَالَ يَمْرَضُ الْعَبْدُ مِنْ عِبَادِي مِمَّنْ فِي الْأَرْضِ فَلَا يُعَادُ فَلَوْ ‏ ‏عَادَهُ ‏ ‏كَانَ مَا ‏ ‏يَعُودُهُ ‏ ‏لِي وَيَظْمَأُ فِي الْأَرْضِ فَلَا يُسْقَى فَلَوْ سُقِيَ كَانَ مَا سَقَاهُ لِي ‏","","",""],[8875,8875,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجَنَّةِ لَشَجَرَةً يَسِيرُ الرَّاكِبُ ‏ ‏الْجَوَادُ ‏ ‏فِي ظِلِّهَا مِائَةَ سَنَةٍ وَإِنَّ وَرَقَهَا ‏ ‏لَيُخَمِّرُ ‏ ‏الْجَنَّةَ ‏","","",""],[8876,8876,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ ‏ ‏مُرَابِطًا ‏ ‏وُقِيَ فِتْنَةَ الْقَبْرِ وَأُومِنَ مِنْ الْفَزَعِ الْأَكْبَرِ ‏ ‏وَغُدِيَ عَلَيْهِ وَرِيحَ بِرِزْقِهِ مِنْ الْجَنَّةِ وَكُتِبَ لَهُ أَجْرُ ‏ ‏الْمُرَابِطِ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[8877,8877,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ صِبْرَةَ ‏ ‏وَعَبَّادُ بْنُ مَنْصُورٍ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقْبَلُ ‏ ‏الصَّدَقَةَ ‏ ‏وَلَا يَقْبَلُ مِنْهَا إِلَّا الطَّيِّبَ يَقْبَلُهَا بِيَمِينِهِ تَبَارَكَ وَتَعَالَى ‏ ‏وَيُرَبِّيهَا لِعَبْدِهِ الْمُسْلِمِ اللُّقْمَةَ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏مُهْرَهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى ‏ ‏يُوَافَى ‏ ‏بِهَا يَوْمَ الْقِيَامَةِ مِثْلَ ‏ ‏أُحُدٍ ‏","","",""],[8878,8878,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلَ عَبْدٌ الْجَنَّةَ بِغُصْنِ شَوْكٍ عَلَى ظَهْرِ طَرِيقِ الْمُسْلِمِينَ فَأَمَاطَهُ عَنْهُ ‏","","",""],[8879,8879,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدْعُو عِنْدَ النَّوْمِ اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيمِ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ ‏ ‏فَالِقَ ‏ ‏الْحَبِّ وَالنَّوَى لَا إِلَهَ إِلَّا أَنْتَ أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ ‏ ‏بِنَاصِيَتِهِ ‏ ‏أَنْتَ الْأَوَّلُ لَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ لَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ لَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ لَيْسَ دُونَكَ شَيْءٌ اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنْ الْفَقْرِ ‏","","",""],[8880,8880,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[8881,8881,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏كَانَ ‏ ‏يَمُرُّ بِآلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِلَالٌ ثُمَّ هِلَالٌ لَا يُوقَدُ فِي شَيْءٍ مِنْ بُيُوتِهِمْ النَّارُ لَا لِخُبْزٍ وَلَا لِطَبِيخٍ فَقَالُوا بِأَيِّ شَيْءٍ كَانُوا يَعِيشُونَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ بِالْأَسْوَدَيْنِ التَّمْرِ وَالْمَاءِ وَكَانَ لَهُمْ جِيرَانٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَجَزَاهُمْ اللَّهُ خَيْرًا لَهُمْ ‏ ‏مَنَائِحُ ‏ ‏يُرْسِلُونَ إِلَيْهِمْ شَيْئًا مِنْ لَبَنٍ ‏","","",""],[8882,8882,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَهَادَوْا فَإِنَّ الْهَدِيَّةَ تُذْهِبُ ‏ ‏وَغَرَ ‏ ‏الصَّدْرِ ‏","","",""],[8883,8883,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَمَّرَ سِتِّينَ سَنَةً أَوْ سَبْعِينَ سَنَةً فَقَدْ ‏ ‏عُذِرَ ‏ ‏إِلَيْهِ فِي الْعُمُرِ ‏","","",""],[8884,8884,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏الطُّهَوِيِّ ‏ ‏عَنْ ‏ ‏ذُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْمَلْنَا ‏ ‏وَأَنْفَضْنَا ‏ ‏فَآتَيْنَا عَلَى إِبِلٍ ‏ ‏مَصْرُورَةٍ ‏ ‏بِلِحَاءِ ‏ ‏الشَّجَرِ ‏ ‏فَابْتَدَرَهَا ‏ ‏الْقَوْمُ لِيَحْلِبُوهَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ عَسَى أَنْ يَكُونَ فِيهَا ‏ ‏قُوتُ ‏ ‏أَهْلِ بَيْتٍ مِنْ الْمُسْلِمِينَ أَتُحِبُّونَ لَوْ أَنَّهُمْ أَتَوْا عَلَى مَا فِي ‏ ‏أَزْوَادِكُمْ ‏ ‏فَأَخَذُوهُ ثُمَّ قَالَ إِنْ كُنْتُمْ لَا بُدَّ فَاعِلِينَ فَاشْرَبُوا وَلَا تَحْمِلُوا ‏","","",""],[8885,8885,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدَعُوا رَكْعَتَيْ الْفَجْرِ وَإِنْ طَرَدَتْكُمْ الْخَيْلُ ‏","","",""],[8886,8886,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏مَنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي وَمَنْ ذَكَرَنِي فِي مَلَإٍ مِنْ النَّاسِ ذَكَرْتُهُ فِي مَلَإٍ أَكْثَرَ مِنْهُمْ وَأَطْيَبَ ‏","","",""],[8887,8887,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[8888,8888,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَاصٌّ ‏ ‏يُقَالُ ‏ ‏لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ ‏ ‏قَالَ فَسَمِعْتُهُ يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ عَبْدًا ‏ ‏أَصَابَ ‏ ‏ذَنْبًا فَقَالَ أَيْ رَبِّ أَذْنَبْتُ ذَنْبًا فَاغْفِرْ لِي فَقَالَ رَبُّهُ عَزَّ وَجَلَّ ‏ ‏عَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ فَغَفَرَ لَهُ ثُمَّ مَكَثَ مَا شَاءَ اللَّهُ ثُمَّ أَذْنَبَ ذَنْبًا آخَرَ فَقَالَ أَيْ رَبِّ أَذْنَبْتُ ذَنْبًا فَاغْفِرْهُ لِي فَقَالَ رَبُّهُ عَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِهِ قَدْ غَفَرْتُ لِعَبْدِي ‏","","",""],[8889,8889,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏زَكَرِيَّا ‏ ‏نَجَّارًا ‏","","",""],[8890,8890,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدَعُوا رَكْعَتَيْ الْفَجْرِ وَإِنْ ‏ ‏طَرَدَتْكُمْ ‏ ‏الْخَيْلُ ‏","","",""],[8891,8891,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏دَاوُدُ بْنُ فَرَاهِيجَ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ لَنَا طَعَامٌ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ ‏","","",""],[8892,8892,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الَّذِي يَسْمَعُ الْحِكْمَةَ وَيَتَّبِعُ شَرَّ مَا يَسْمَعُ كَمَثَلِ رَجُلٍ أَتَى رَاعِيًا فَقَالَ لَهُ ‏ ‏أَجْزِرْنِي ‏ ‏شَاةً مِنْ غَنَمِكَ فَقَالَ اذْهَبْ فَخُذْ بِأُذُنِ خَيْرِهَا شَاةً فَذَهَبَ فَأَخَذَ بِأُذُنِ كَلْبِ الْغَنَمِ ‏","","",""],[8893,8893,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ رَاشِدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَرُّ الطَّعَامِ طَعَامُ ‏ ‏الْوَلِيمَةِ ‏ ‏يُدْعَى لَهَا الْأَغْنِيَاءُ وَيُدْفَعُ ‏ ‏عَنْهَا الْفُقَرَاءُ وَمَنْ تَرَكَ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[8894,8894,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ قَالُوا يَا رَسُولَ اللَّهِ وَمَا الْفَأْلُ قَالَ الْكَلِمَةُ الصَّالِحَةُ يَسْمَعُهَا أَحَدُكُمْ ‏","","",""],[8895,8895,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُورَدُ ‏ ‏مُمْرِضٌ عَلَى ‏ ‏مُصِحٍّ ‏","","",""],[8896,8896,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أُتِيَ بِطَعَامٍ مِنْ غَيْرِ أَهْلِهِ سَأَلَ عَنْهُ فَإِنْ قِيلَ هَدِيَّةٌ أَكَلَ وَإِنْ قِيلَ ‏ ‏صَدَقَةٌ ‏ ‏قَالَ كُلُوا وَلَمْ يَأْكُلْ ‏","","",""],[8897,8897,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَأَى رَجُلًا مُبَقَّعَ الرِّجْلَيْنِ فَقَالَ أَحْسِنُوا الْوُضُوءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[8898,8898,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الدَّابَّةُ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏وَمَنْ ابْتَاعَ شَاةً فَوَجَدَهَا ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏إِنْ شَاءَ رَدَّهَا ‏ ‏وَصَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[8899,8899,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِتَمْرٍ مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَمَرَ فِيهِ بِأَمْرِهِ فَحَمَلَ ‏ ‏الْحَسَنَ ‏ ‏أَوْ ‏ ‏الْحُسَيْنَ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فَجَعَلَ لُعَابُهُ يَسِيلُ عَلَيْهِ فَنَظَرَ إِلَيْهِ فَإِذَا هُوَ يَلُوكُ تَمْرَةً فَحَرَّكَ خَدَّهُ وَقَالَ أَلْقِهَا يَا بُنَيَّ أَمَا شَعَرْتَ ‏ ‏أَنَّ آلَ ‏ ‏مُحَمَّدٍ ‏ ‏لَا يَأْكُلُونَ ‏ ‏الصَّدَقَةَ ‏","","",""],[8900,8900,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَطَاعَ الْعَبْدُ رَبَّهُ وَسَيِّدَهُ فَلَهُ أَجْرَانِ ‏","","",""],[8901,8901,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ قَدْ كَفَاهُ ‏ ‏حَرَّهُ ‏ ‏وَعَمَلَهُ فَإِنْ لَمْ يُقْعِدْهُ مَعَهُ لِيَأْكُلَ فَلْيُنَاوِلْهُ أُكْلَةً مِنْ طَعَامِهِ ‏","","",""],[8902,8902,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ آدَمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَنْبِيَاءُ إِخْوَةٌ لِعَلَّاتٍ ‏ ‏أُمَّهَاتُهُمْ شَتَّى وَدِينُهُمْ وَاحِدٌ وَأَنَا أَوْلَى النَّاسِ ‏ ‏بِعِيسَى ابْنِ مَرْيَمَ ‏ ‏لِأَنَّهُ لَمْ يَكُنْ بَيْنِي وَبَيْنَهُ نَبِيٌّ وَإِنَّهُ نَازِلٌ فَإِذَا رَأَيْتُمُوهُ فَاعْرِفُوهُ رَجُلًا ‏ ‏مَرْبُوعًا ‏ ‏إِلَى الْحُمْرَةِ وَالْبَيَاضِ عَلَيْهِ ثَوْبَانِ ‏ ‏مُمَصَّرَانِ ‏ ‏كَأَنَّ رَأْسَهُ يَقْطُرُ وَإِنْ لَمْ يُصِبْهُ بَلَلٌ فَيَدُقُّ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ الْجِزْيَةَ وَيَدْعُو النَّاسَ إِلَى الْإِسْلَامِ فَيُهْلِكُ اللَّهُ فِي زَمَانِهِ الْمِلَلَ كُلَّهَا إِلَّا الْإِسْلَامَ وَيُهْلِكُ اللَّهُ فِي زَمَانِهِ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏وَتَقَعُ الْأَمَنَةُ عَلَى الْأَرْضِ حَتَّى ‏ ‏تَرْتَعَ ‏ ‏الْأُسُودُ مَعَ الْإِبِلِ ‏ ‏وَالنِّمَارُ مَعَ الْبَقَرِ وَالذِّئَابُ مَعَ الْغَنَمِ وَيَلْعَبَ الصِّبْيَانُ بِالْحَيَّاتِ لَا تَضُرُّهُمْ فَيَمْكُثُ أَرْبَعِينَ سَنَةً ثُمَّ يُتَوَفَّى وَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ ‏","","",""],[8903,8903,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ رِجَالٍ يُقَادُونَ إِلَى الْجَنَّةِ فِي السَّلَاسِلِ ‏","","",""],[8904,8904,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى قَبْرٍ ‏","","",""],[8905,8905,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْجَبَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ تَقُولُ يَا رَبِّ إِنِّي قُطِعْتُ يَا رَبِّ إِنِّي أُسِيءَ إِلَيَّ يَا رَبِّ إِنِّي ظُلِمْتُ يَا رَبِّ قَالَ فَيُجِيبُهَا ‏ ‏أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ ‏","","",""],[8906,8906,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ قَوْمٍ يَجْتَمِعُونَ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ عَزَّ وَجَلَّ يَقْرَءُونَ وَيَتَعَلَّمُونَ كِتَابَ اللَّهِ عَزَّ وَجَلَّ يَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا ‏ ‏حَفَّتْ ‏ ‏بِهِمْ الْمَلَائِكَةُ ‏ ‏وَغَشِيَتْهُمْ ‏ ‏الرَّحْمَةُ وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ وَمَا مِنْ رَجُلٍ يَسْلُكُ طَرِيقًا ‏ ‏يَلْتَمِسُ ‏ ‏بِهِ الْعِلْمَ إِلَّا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ وَمَنْ يُبْطِئُ بِهِ عَمَلُهُ لَا يُسْرِعُ بِهِ نَسَبُهُ ‏","","",""],[8907,8907,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8908,8908,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَاسْتَقْبَلَتْنَا ‏ ‏رِجْلٌ ‏ ‏مِنْ جَرَادٍ فَجَعَلْنَا نَضْرِبُهُنَّ بِسِيَاطِنَا وَعِصِيِّنَا نَقْتُلُهُنَّ فَسُقِطَ فِي أَيْدِينَا فَقُلْنَا مَا صَنَعْنَا وَنَحْنُ مُحْرِمُونَ فَسَأَلْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا بَأْسَ صَيْدُ الْبَحْرِ ‏","","",""],[8909,8909,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏طَعَامُ الْوَاحِدِ يَكْفِي ‏ ‏الِاثْنَيْنِ وَطَعَامُ ‏ ‏الِاثْنَيْنِ يَكْفِي الْأَرْبَعَةَ ‏","","",""],[8910,8910,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ رِيَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏بِالْأَعْمَالِ سِتًّا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَالدَّجَّالَ ‏ ‏وَالدُّخَانَ وَدَابَّةَ الْأَرْضِ ‏ ‏وَخُوَيْصَّةَ ‏ ‏أَحَدِكُمْ وَأَمْرَ الْعَامَّةِ ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَقُولُ ‏ ‏إِذَا قَالَ وَأَمْرَ الْعَامَّةِ قَالَ أَيْ أَمْرُ السَّاعَةِ ‏","","",""],[8911,8911,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسِبُ ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏إِنَّهُ مَنْ يَدْخُلْ الْجَنَّةَ يَنْعَمْ وَلَا يَبْأَسْ لَا ‏ ‏تَبْلَى ‏ ‏ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[8912,8912,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏شُتَيْرِ بْنِ نَهَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُسْنُ الظَّنِّ مِنْ حُسْنِ الْعِبَادَةِ ‏","","",""],[8913,8913,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُثَيْمُ بْنُ عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ فِي عَبْدِ الرَّجُلِ وَلَا فِي فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[8914,8914,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسِبُ ‏ ‏حَمَّادٌ ‏ ‏أَنَّ ‏ ‏رَجُلًا كَانَ يَبِيعُ الْخَمْرَ فِي سَفِينَةٍ وَمَعَهُ فِي السَّفِينَةِ قِرْدٌ فَكَانَ يَشُوبُ الْخَمْرَ بِالْمَاءِ قَالَ فَأَخَذَ الْقِرْدُ الْكِيسَ ثُمَّ صَعِدَ بِهِ فَوْقَ الدُّورِ وَفَتَحَ الْكِيسَ فَجَعَلَ يَأْخُذُ دِينَارًا فَيُلْقِهِ فِي السَّفِينَةِ وَدِينَارًا فِي الْبَحْرِ حَتَّى جَعَلَهُ نِصْفَيْنِ ‏","","",""],[8915,8915,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَأَى رَجُلًا مُبَقَّعَ الرِّجْلَيْنِ فَقَالَ أَحْسِنُوا الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْعَقِبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[8916,8916,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَاحِبٌ لَنَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ صَوْمِ يَوْمِ الْجُمُعَةِ إِلَّا صَوْمًا مُتَتَابِعًا ‏","","",""],[8917,8917,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ إِبْرَاهِيمَ الْقُرَشِيِّ ‏ ‏أَوْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو فِي ‏ ‏دُبُرِ ‏ ‏صَلَاةِ الظُّهْرِ ‏ ‏اللَّهُمَّ خَلِّصْ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏وَسَلَمَةَ بْنَ هِشَامٍ ‏ ‏وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏وَضَعَفَةَ الْمُسْلِمِينَ مِنْ أَيْدِي الْمُشْرِكِينَ الَّذِينَ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا ‏","","",""],[8918,8918,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْكُفْرُ قِبَلَ الْمَشْرِقِ ‏ ‏وَالسَّكِينَةُ ‏ ‏فِي أَهْلِ الْغَنَمِ وَالْفَخْرُ ‏ ‏وَالرِّيَاءُ ‏ ‏فِي ‏ ‏الْفَدَّادِينَ ‏ ‏يَأْتِي ‏ ‏الْمَسِيحُ ‏ ‏مِنْ قِبَلِ الْمَشْرِقِ وَهِمَّتُهُ ‏ ‏الْمَدِينَةَ ‏ ‏حَتَّى إِذَا جَاءَ ‏ ‏دُبُرَ ‏ ‏أُحُدٍ ‏ ‏ضَرَبَتْ ‏ ‏الْمَلَائِكَةُ وَجْهَهُ قِبَلَ ‏ ‏الشَّامِ ‏ ‏هُنَالِكَ يَهْلِكُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً صَرَفَتْ الْمَلَائِكَةُ وَجْهَهُ ‏","","",""],[8919,8919,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَدَّمُوا بَيْنَ يَدَيْ رَمَضَانَ بِصَوْمِ يَوْمٍ وَلَا يَوْمَيْنِ إِلَّا رَجُلٌ كَانَ صِيَامَهُ فَلْيَصُمْهُ ‏","","",""],[8920,8920,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏فَإِنَّهُ يُغْفَرُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[8921,8921,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏فَإِنَّهُ يُغْفَرُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏بِمِثْلِهِ ‏","","",""],[8922,8922,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَكِيمٌ الْأَثْرَمُ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَتَى ‏ ‏حَائِضًا أَوْ امْرَأَةً فِي ‏ ‏دُبُرِهَا ‏ ‏أَوْ ‏ ‏كَاهِنًا ‏ ‏فَصَدَّقَهُ فَقَدْ بَرِئَ مِمَّا أَنْزَلَ اللَّهُ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏","","",""],[8923,8923,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا رَفَعَهُ ثُمَّ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أُرَاهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا زَارَ أَخًا لَهُ فِي قَرْيَةٍ أُخْرَى ‏ ‏فَأَرْصَدَ ‏ ‏اللَّهُ عَلَى ‏ ‏مَدْرَجَتِهِ ‏ ‏مَلَكًا فَلَمَّا أَتَى عَلَيْهِ قَالَ الْمَلَكُ أَيْنَ تُرِيدُ قَالَ أَزُورُ أَخًا لِي فِي هَذِهِ الْقَرْيَةِ قَالَ هَلْ لَهُ عَلَيْكَ مِنْ نِعْمَةٍ ‏ ‏تَرُبُّهَا ‏ ‏قَالَ لَا إِلَّا أَنِّي أَحْبَبْتُهُ فِي اللَّهِ عَزَّ وَجَلَّ قَالَ فَإِنِّي ‏ ‏يَعْنِي رَسُولُ اللَّهِ إِلَيْكَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَحَبَّكَ كَمَا أَحْبَبْتَهُ ‏","","",""],[8924,8924,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَقْبَرَةِ فَسَلَّمَ عَلَى أَهْلِهَا قَالَ ‏ ‏سَلَامٌ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ وَدِدْتُ أَنَّا قَدْ رَأَيْنَا إِخْوَانَنَا قَالُوا أَوَلَسْنَا إِخْوَانَكَ يَا رَسُولَ اللَّهِ قَالَ بَلْ أَنْتُمْ أَصْحَابِي وَإِخْوَانِي الَّذِينَ لَمْ يَأْتُوا بَعْدُ وَأَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ قَالُوا وَكَيْفَ تَعْرِفُ مَنْ لَمْ يَأْتِ بَعْدُ مِنْ أُمَّتِكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أَرَأَيْتَ ‏ ‏لَوْ أَنَّ رَجُلًا لَهُ خَيْلٌ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلَةٌ ‏ ‏بَيْنَ ظَهْرَيْ خَيْلٍ ‏ ‏دُهْمٍ ‏ ‏بُهْمٍ ‏ ‏أَلَا يَعْرِفُ خَيْلَهُ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهُمْ يَأْتُونَ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ الْوُضُوءِ يَقُولُهَا ثَلَاثًا وَأَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ أَلَا ‏ ‏لَيُذَادَنَّ ‏ ‏رِجَالٌ عَنْ حَوْضِي كَمَا ‏ ‏يُذَادُ ‏ ‏الْبَعِيرُ الضَّالُّ ‏ ‏أُنَادِيهِمْ أَلَا ‏ ‏هَلُمَّ ‏ ‏أَلَا ‏ ‏هَلُمَّ ‏ ‏فَيُقَالُ إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ فَأَقُولُ ‏ ‏سُحْقًا ‏ ‏سُحْقًا ‏","","",""],[8925,8925,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَزْرَقِ ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏جَالِسًا ذَاتَ يَوْمٍ بِالسُّوقِ فَمُرَّ بِجِنَازَةٍ ‏ ‏يُبْكَى عَلَيْهَا فَعَابَ ذَلِكَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَانْتَهَرَهُمْ فَقَالَ لَهُ ‏ ‏سَلَمَةُ بْنُ الْأَزْرَقِ ‏ ‏لَا تَقُلْ ذَلِكَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَأَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَسَمِعْتُهُ وَتُوُفِّيَتْ امْرَأَةٌ مِنْ ‏ ‏كَنَائِنِ ‏ ‏مَرْوَانَ ‏ ‏فَشَهِدَهَا ‏ ‏مَرْوَانُ ‏ ‏فَأَمَرَ بِالنِّسَاءِ اللَّاتِي يَبْكِينَ فَضُرِبْنَ فَقَالَ لَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏دَعْهُنَّ يَا ‏ ‏أَبَا عَبْدِ الْمَلِكِ ‏ ‏فَإِنَّهُ مُرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ ‏ ‏يُبْكَى عَلَيْهَا وَأَنَا مَعَهُ وَمَعَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَحِمَهُ اللَّهُ فَانْتَهَرَ ‏ ‏عُمَرُ ‏ ‏اللَّاتِي يَبْكِينَ مَعَ الْجِنَازَةِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ ‏ ‏النَّفْسَ مُصَابَةٌ وَإِنَّ الْعَيْنَ دَامِعَةٌ وَإِنَّ الْعَهْدَ لَحَدِيثٌ ‏ ‏قَالَ ‏ ‏أَنْتَ سَمِعْتَهُ فَقَالَ نَعَمْ قَالَ اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏","","",""],[8926,8926,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ الْعَنْبَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ مِنْ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[8927,8927,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏صَاحِبُ ‏ ‏الزِّيَادِيِّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ أَهْلِ الْعِلْمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَا مِنْ مُسْلِمٍ يَمُوتُ فَيَشْهَدُ لَهُ ثَلَاثَةُ أَهْلِ أَبْيَاتٍ مِنْ جِيرَانِهِ الْأَدْنَيْنَ بِخَيْرٍ إِلَّا قَالَ تَبَارَكَ وَتَعَالَى قَدْ ‏ ‏قَبِلْتُ شَهَادَةَ عِبَادِي عَلَى ‏ ‏مَا عَلِمُوا وَغَفَرْتُ لَهُ مَا أَعْلَمُ ‏","","",""],[8928,8928,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَزَادَنِي ‏ ‏غَيْرُ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْذَبُ النَّاسِ الصُّنَّاعُ ‏","","",""],[8929,8929,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي كَثِيرٍ الْغُبَرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[8930,8930,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ امْرَأَتِي وَلَدَتْ غُلَامًا أَسْوَدَ فَقَالَ ‏ ‏هَلْ لَكَ مِنْ إِبِلٍ قَالَ نَعَمْ قَالَ فَمَا أَلْوَانُهَا قَالَ ‏ ‏رُمْكٌ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرُبَّمَا لَيْسَ جَاءَتْ بِالْبَعِيرِ ‏ ‏الْأَوْرَقِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ نَعَمْ قَالَ فَأَنَّى ‏ ‏تَرَى ذَلِكَ قَالَ أُرَاهُ ‏ ‏نَزَعَهُ ‏ ‏عِرْقٌ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذَا ‏ ‏نَزَعَهُ ‏ ‏عِرْقٌ ‏","","",""],[8931,8931,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الزُّرَقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏بِطَرِيقِ ‏ ‏مَكَّةَ ‏ ‏إِذْ هَاجَتْ رِيحٌ فَقَالَ لِمَنْ حَوْلَهُ الرِّيحَ قَالَ فَلَمْ يَرُدُّوا عَلَيْهِ شَيْئًا قَالَ فَبَلَغَنِي الَّذِي سَأَلَ عَنْهُ مِنْ ذَلِكَ فَاسْتَحْثَثْتُ رَاحِلَتِي حَتَّى أَدْرَكْتُهُ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ بَلَغَنِي أَنَّكَ سَأَلْتَ عَنْ الرِّيحِ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرِّيحُ مِنْ رَوْحِ اللَّهِ فَلَا تَسُبُّوهَا وَسَلُوا خَيْرَهَا وَاسْتَعِيذُوا بِهِ مِنْ شَرِّهَا ‏","","",""],[8932,8932,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ الْأَصَمِّ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏بِالْمَدِينَةِ ‏ ‏مَعَ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏فَمَرَّتْ بِهِمَا جِنَازَةٌ فَقَامَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَلَمْ يَقُمْ ‏ ‏مَرْوَانُ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ بِهِ جِنَازَةٌ ‏ ‏فَقَامَ فَقَامَ عِنْدَ ذَلِكَ ‏ ‏مَرْوَانُ ‏","","",""],[8933,8933,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ نَهَى عَنْ ‏ ‏الْفَرَعِ ‏ ‏وَالْعَتِيرَةِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَقَدْ سَمِعْتُهُ أَنَا مِنْ ‏ ‏مَعْمَرٍ ‏","","",""],[8934,8934,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْوَلَدُ لِصَاحِبِ ‏ ‏الْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[8935,8935,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِكُلِّ نَبِيٍّ دَعْوَةٌ دَعَا بِهَا فِي أُمَّتِهِ فَيُسْتَجَابُ لَهُ وَإِنِّي ‏ ‏أُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أُؤَخِّرَ دَعْوَتِي ‏ ‏شَفَاعَةً ‏ ‏لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[8936,8936,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَأْتِي عَلَى النَّاسِ وَهُمْ يَتَوَضَّئُونَ فِي الْمَطْهَرَةِ فَيَقُولُ لَهُمْ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[8937,8937,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَسْتَعْمِلُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَكَانَ إِذَا رَأَى إِنْسَانًا يَجُرُّ إِزَارَهُ ضَرَبَ بِرِجْلِهِ ثُمَّ يَقُولُ قَدْ جَاءَ الْأَمِيرُ قَدْ جَاءَ الْأَمِيرُ ثُمَّ يَقُولُ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[8938,8938,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحْفِهِمَا جَمِيعًا أَوْ أَنْعِلْهُمَا جَمِيعًا فَإِذَا لَبِسْتَ فَابْدَأْ بِالْيَمِينِ وَإِذَا خَلَعْتَ فَابْدَأْ بِالْيُسْرَى ‏","","",""],[8939,8939,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدَكُمْ خَادِمُهُ بِطَعَامٍ فَإِنْ لَمْ يُجْلِسْهُ مَعَهُ فَلْيُنَاوِلْهُ أُكْلَةً أَوْ أُكْلَتَيْنِ ‏ ‏أَوْ لُقْمَةً أَوْ لُقْمَتَيْنِ ‏ ‏شُعْبَةُ ‏ ‏شَكَّ ‏ ‏فَإِنَّهُ ‏ ‏وَلِيَ ‏ ‏عِلَاجَهُ ‏ ‏وَحَرَّهُ ‏","","",""],[8940,8940,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏الْحَسَنَ ‏ ‏أَخَذَ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَجَعَلَهَا فِي ‏ ‏فِيهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِخْ كِخْ أَلْقِهَا أَمَا شَعَرْتَ ‏ ‏أَنَّا أَهْلَ بَيْتٍ لَا نَأْكُلُ ‏ ‏الصَّدَقَةَ ‏","","",""],[8941,8941,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏لَوْ أَنَّ ‏ ‏الْأَنْصَارَ ‏ ‏سَلَكُوا وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏وَسَلَكَ النَّاسُ وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا ظَلَمَ بِأَبِي وَأُمِّي لَقَدْ آوَوْهُ وَنَصَرُوهُ وَكَلِمَةً أُخْرَى ‏","","",""],[8942,8942,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏تُصَرُّوا ‏ ‏الْإِبِلَ وَالْغَنَمَ فَمَنْ اشْتَرَى ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ بِأَحَدِ ‏ ‏النَّظَرَيْنِ ‏ ‏إِنْ شَاءَ رَدَّهَا وَرَدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ قَالَ وَلَا يَبِيعُ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ وَلَا تَسْأَلُ الْمَرْأَةُ طَلَاقَ أُخْتِهَا ‏ ‏لِتَكْتَفِئَ ‏ ‏مَا فِي صَحْفَتِهَا فَإِنَّ مَالَهَا مَا كُتِبَ لَهَا وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَلَقَّوْا الْأَجْلَابَ ‏","","",""],[8943,8943,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَجَّ هَذَا ‏ ‏الْبَيْتَ ‏ ‏فَلَمْ ‏ ‏يَرْفُثْ ‏ ‏وَلَمْ يَفْسُقْ رَجَعَ كَمَا وَلَدَتْهُ أُمُّهُ ‏","","",""],[8944,8944,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا وُضُوءَ إِلَّا مِنْ ‏ ‏حَدَثٍ ‏ ‏أَوْ رِيحٍ ‏","","",""],[8945,8945,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَجَّ هَذَا ‏ ‏الْبَيْتَ ‏ ‏فَلَمْ ‏ ‏يَرْفُثْ ‏ ‏وَلَمْ يَفْسُقْ رَجَعَ كَمَا وَلَدَتْهُ أُمُّهُ ‏","","",""],[8946,8946,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى غُلَامِ الْمُسْلِمِ وَلَا عَلَى فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[8947,8947,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ الْمُحَارِبِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا قُعُودًا مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏فَأَذَّنَ الْمُؤَذِّنُ فَقَامَ رَجُلٌ فِي الْمَسْجِدِ فَخَرَجَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَمَّا هَذَا فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[8948,8948,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي إِنَّ الشَّيْطَانَ لَا يَتَصَوَّرُ بِي ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ لَا يَتَشَبَّهُ بِي ‏ ‏وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[8949,8949,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ وَيُشْرِكَانِهِ ‏","","",""],[8950,8950,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَيْرُكُمْ ‏ ‏قَرْنِي ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَا أَدْرِي ذَكَرَ مَرَّتَيْنِ أَوْ ثَلَاثًا ‏ ‏ثُمَّ خَلَفَ مِنْ بَعْدِهِمْ قَوْمٌ يُحِبُّونَ السِّمَانَةَ يَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ ‏","","",""],[8951,8951,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ أَبِي سَعِيدٍ الْمَقْبُرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَسْفَلَ مِنْ الْكَعْبَيْنِ فَفِي النَّارِ ‏ ‏يَعْنِي ‏ ‏الْإِزَارَ ‏","","",""],[8952,8952,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْلَسَ رَجُلٌ بِمَالِ قَوْمٍ فَرَأَى رَجُلٌ مَتَاعَهُ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ مِنْ غَيْرِهِ ‏","","",""],[8953,8953,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ مِنْ الْفِطْرَةِ ‏ ‏الْخِتَانُ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَنَتْفُ الْإِبْطِ وَتَقْلِيمُ الْأَظْفَارِ وَقَصُّ الشَّارِبِ ‏","","",""],[8954,8954,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ الْقُرْدُوسِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ يَدَعُ طَعَامَهُ وَشَرَابَهُ مِنْ ‏ ‏جَرَّايَ ‏ ‏الصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ عِنْدَ اللَّهِ عَزَّ وَجَلَّ أَطْيَبُ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8955,8955,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ مَنْ عَاشَ مِنْكُمْ أَنْ يَلْقَى ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏إِمَامًا مَهْدِيًّا وَحَكَمًا عَدْلًا فَيَكْسِرُ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ ‏ ‏الْجِزْيَةَ ‏ ‏وَتَضَعُ الْحَرْبُ ‏ ‏أَوْزَارَهَا ‏","","",""],[8956,8956,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ بِي ‏","","",""],[8957,8957,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةٌ فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشْرُ أَمْثَالِهَا إِلَى سَبْعِ مِائَةٍ وَسَبْعِ أَمْثَالِهَا فَإِنْ لَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةٌ وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ عَلَيْهِ ‏","","",""],[8958,8958,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏الْفَأْرَةُ مِمَّا مُسِخَ ‏ ‏وَآيَةُ ‏ ‏ذَلِكَ أَنَّهُ يُوضَعُ لَهَا لَبَنُ ‏ ‏اللِّقَاحِ ‏ ‏فَلَا تَقْرَبُهُ وَإِذَا وُضِعَ لَهَا لَبَنُ الْغَنَمِ أَصَابَتْ مِنْهُ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏كَعْبٌ ‏ ‏سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَأُنْزِلَتْ عَلَيَّ التَّوْرَاةُ ‏","","",""],[8959,8959,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْبَهِيمَةُ ‏ ‏عَقْلُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[8960,8960,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤَذِّنُ يُغْفَرُ لَهُ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ حَسَنَةً وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[8961,8961,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ وَإِنْ صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ‏","","",""],[8962,8962,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ أَظُنُّهُ حَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏فِي كُلِّ الصَّلَوَاتِ يَقْرَأُ فِيهَا ‏ ‏فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏","","",""],[8963,8963,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَاللِّسَانُ يَزْنِي وَالْيَدَانِ تَزْنِيَانِ وَالرِّجْلَانِ تَزْنِيَانِ وَيُحَقِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ الْفَرْجُ ‏","","",""],[8964,8964,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسِيرُ فِي طَرِيقِ ‏ ‏مَكَّةَ ‏ ‏فَأَتَى عَلَى ‏ ‏جُمْدَانَ ‏ ‏فَقَالَ هَذَا ‏ ‏جُمْدَانُ ‏ ‏سِيرُوا سَبَقَ ‏ ‏الْمُفَرِّدُونَ ‏ ‏قَالُوا وَمَا الْمُفَرِّدُونَ قَالَ الذَّاكِرُونَ اللَّهَ كَثِيرًا ثُمَّ قَالَ اللَّهُمَّ اغْفَرْ لِلْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ لِلْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ قَالَ وَالْمُقَصِّرِينَ ‏","","",""],[8965,8965,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتُؤَدُّنَّ الْحُقُوقَ إِلَى أَهْلِهَا حَتَّى ‏ ‏يُقَادَ ‏ ‏لِلشَّاةِ ‏ ‏الْجَلْحَاءِ ‏ ‏مِنْ الشَّاةِ ‏ ‏الْقَرْنَاءِ ‏","","",""],[8966,8966,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا ‏ ‏يَسُومُ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ الْمُسْلِمِ وَلَا يَخْطُبُ عَلَى خِطْبَتِهِ ‏","","",""],[8967,8967,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذَا الْحَرَّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏","","",""],[8968,8968,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعَ الشَّيْطَانُ الْأَذَانَ ‏ ‏وَلَّى ‏ ‏وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ الصَّوْتَ ‏","","",""],[8969,8969,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُضِّلْتُ عَلَى الْأَنْبِيَاءِ بِسِتٍّ قِيلَ مَا هُنَّ أَيْ رَسُولَ اللَّهِ قَالَ ‏ ‏أُعْطِيتُ ‏ ‏جَوَامِعَ الْكَلِمِ ‏ ‏وَنُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَأُحِلَّتْ لِي الْغَنَائِمُ وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا وَأُرْسِلْتُ إِلَى الْخَلْقِ كَافَّةً وَخُتِمَ ‏ ‏بِيَ النَّبِيُّونَ مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ عَلَيْهِمْ الصَّلَاةُ وَالسَّلَامُ كَمَثَلِ رَجُلٍ بَنَى قَصْرًا فَأَكْمَلَ بِنَاءَهُ وَأَحْسَنَ بُنْيَانَهُ إِلَّا مَوْضِعَ ‏ ‏لَبِنَةٍ ‏ ‏فَنَظَرَ النَّاسُ إِلَى الْقَصْرِ فَقَالُوا مَا أَحْسَنَ بُنْيَانَ هَذَا الْقَصْرِ لَوْ تَمَّتْ هَذِهِ ‏ ‏اللَّبِنَةُ ‏ ‏أَلَا فَكُنْتُ أَنَا ‏ ‏اللَّبِنَةَ ‏ ‏أَلَا فَكُنْتُ أَنَا ‏ ‏اللَّبِنَةَ ‏","","",""],[8970,8970,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْبَرِي عَلَى تُرْعَةٍ مِنْ ‏ ‏تُرَعِ ‏ ‏الْجَنَّةِ وَمَا بَيْنَ مِنْبَرِي وَحُجْرَتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏","","",""],[8971,8971,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقُولُ الْعَبْدُ مَالِي وَإِنَّ مَا لَهُ مِنْ مَالِهِ ثَلَاثٌ مَا أَكَلَ فَأَفْنَى أَوْ لَبِسَ فَأَبْلَى أَوْ أَعْطَى فَأَقْنَى مَا سِوَى ذَلِكَ ذَاهِبٌ وَتَارِكُهُ لِلنَّاسِ ‏","","",""],[8972,8972,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَنْذِرُوا ‏ ‏فَإِنَّ ‏ ‏النَّذْرَ ‏ ‏لَا يُقَدِّمُ مِنْ ‏ ‏الْقَدَرِ ‏ ‏شَيْئًا وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[8973,8973,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الْقَاصُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ سِتٌّ قَالُوا وَمَا هُنَّ يَا رَسُولَ اللَّهِ قَالَ إِذَا لَقِيتَهُ سَلِّمْ عَلَيْهِ وَإِذَا دَعَاكَ فَأَجِبْهُ وَإِذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ ‏ ‏فَشَمِّتْهُ ‏ ‏وَإِذَا مَرِضَ ‏ ‏فَعُدْهُ ‏ ‏وَإِذَا مَاتَ فَاصْحَبْهُ ‏","","",""],[8974,8974,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعُ كَافِرٌ وَقَاتِلُهُ مِنْ الْمُسْلِمِينَ فِي النَّارِ أَبَدًا ‏","","",""],[8975,8975,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي قَرَابَةً أَصِلُهُمْ وَيَقْطَعُونِي وَأَحْلُمُ عَنْهُمْ فَيَجْهَلُونَ عَلَيَّ وَأُحْسِنُ إِلَيْهِمْ وَيُسِيئُونَ إِلَيَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ كَمَا تَقُولُ لَكَأَنَّمَا ‏ ‏تُسِفُّهُمْ ‏ ‏الْمَلَّ ‏ ‏وَلَا يَزَالُ مَعَكَ مِنْ اللَّهِ ظَهِيرٌ عَلَيْهِمْ مَادُمْتَ عَلَى ذَلِكَ ‏","","",""],[8976,8976,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏} ‏فَاشْتَدَّ ذَلِكَ عَلَى صَحَابَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏جَثَوْا ‏ ‏عَلَى الرُّكَبِ فَقَالُوا يَا رَسُولَ اللَّهِ كُلِّفْنَا مِنْ الْأَعْمَالِ مَا نُطِيقُ الصَّلَاةَ وَالصِّيَامَ وَالْجِهَادَ ‏ ‏وَالصَّدَقَةَ ‏ ‏وَقَدْ أُنْزِلَ عَلَيْكَ هَذِهِ الْآيَةُ وَلَا نُطِيقُهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ ‏ ‏قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ فَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ فَلَمَّا أَقَرَّ بِهَا الْقَوْمُ وَذَلَّتْ بِهَا أَلْسِنَتُهُمْ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِي إِثْرِهَا ‏ { ‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ‏} ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَرَأَهَا ‏ ‏سَلَّامٌ أَبُو الْمُنْذِرِ ‏ ‏يُفَرِّقُ ‏ { ‏وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏} ‏فَلَمَّا فَعَلُوا ذَلِكَ ‏ ‏نَسَخَهَا ‏ ‏اللَّهُ تَبَارَكَ وَتَعَالَى بِقَوْلِهِ ‏ { ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا ‏ ‏وُسْعَهَا ‏ ‏لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ‏} ‏فَصَارَ لَهُ مَا كَسَبَتْ مِنْ خَيْرٍ وَعَلَيْهِ مَا اكْتَسَبَتْ مِنْ شَرٍّ فَسَّرَ ‏ ‏الْعَلَاءُ ‏ ‏هَذَا ‏ { ‏رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ‏} ‏قَالَ نَعَمْ ‏ { ‏وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ‏}","","",""],[8977,8977,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَقَالَ يَا ‏ ‏أُبَيُّ ‏ ‏فَالْتَفَتَ فَلَمْ يُجِبْهُ ثُمَّ صَلَّى ‏ ‏أُبَيٌّ ‏ ‏فَخَفَّفَ ثُمَّ انْصَرَفَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ السَّلَامُ عَلَيْكَ أَيْ رَسُولَ اللَّهِ قَالَ وَعَلَيْكَ قَالَ مَا مَنَعَكَ أَيْ ‏ ‏أُبَيُّ ‏ ‏إِذْ دَعَوْتُكَ أَنْ تُجِيبَنِي قَالَ أَيْ رَسُولَ اللَّهِ كُنْتُ فِي الصَّلَاةِ قَالَ أَفَلَسْتَ تَجِدُ فِيمَا أَوْحَى اللَّهُ إِلَيَّ أَنْ ‏ { ‏اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ‏} ‏قَالَ قَالَ بَلَى أَيْ رَسُولَ اللَّهِ لَا أَعُودُ قَالَ أَتُحِبُّ أَنْ أُعَلِّمَكَ سُورَةً لَمْ تَنْزِلْ فِي التَّوْرَاةِ وَلَا فِي الزَّبُورِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الْفُرْقَانِ مِثْلُهَا قَالَ قُلْتُ نَعَمْ أَيْ رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَرْجُو أَنْ لَا تَخْرُجَ مِنْ هَذَا الْبَابِ حَتَّى تَعْلَمَهَا قَالَ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي يُحَدِّثُنِي وَأَنَا أَتَبَطَّأُ مَخَافَةَ أَنْ يَبْلُغَ قَبْلَ أَنْ ‏ ‏يَقْضِيَ ‏ ‏الْحَدِيثَ فَلَمَّا أَنْ ‏ ‏دَنَوْنَا ‏ ‏مِنْ الْبَابِ قُلْتُ أَيْ رَسُولَ اللَّهِ مَا السُّورَةُ الَّتِي وَعَدْتَنِي قَالَ فَكَيْفَ تَقْرَأُ فِي الصَّلَاةِ قَالَ فَقَرَأْتُ عَلَيْهِ ‏ ‏أُمَّ الْقُرْآنِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْزَلَ اللَّهُ فِي التَّوْرَاةِ وَلَا فِي الْإِنْجِيلِ وَلَا فِي الزَّبُورِ وَلَا فِي الْفُرْقَانِ مِثْلَهَا وَإِنَّهَا ‏ ‏لَلسَّبْعُ مِنْ الْمَثَانِي ‏","","",""],[8978,8978,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏أَنَّ فَتًى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَتَى ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَبَخْتَرُ فِي حُلَّةٍ لَهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَجُلًا مِمَّنْ كَانَ قَبْلَكُمْ كَانَ ‏ ‏يَتَبَخْتَرُ ‏ ‏فِي حُلَّةٍ لَهُ قَدْ أَعْجَبَتْهُ ‏ ‏جُمَّتُهُ ‏ ‏وَبُرْدَاهُ ‏ ‏إِذْ ‏ ‏خُسِفَ ‏ ‏بِهِ الْأَرْضُ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِيهَا حَتَّى تَقُومَ السَّاعَةُ ‏","","",""],[8979,8979,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْلَسَ الرَّجُلُ ‏ ‏فَالْغَرِيمُ ‏ ‏أَحَقُّ بِمَتَاعِهِ إِذَا وَجَدَهُ بِعَيْنِهِ ‏","","",""],[8980,8980,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَرَأَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَسَجَدَ قُلْتُ لِمَ أَرَاكَ سَجَدْتَ فِيهَا قَالَ لَوْ لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا مَا سَجَدْتُ ‏","","",""],[8981,8981,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْيَمِينُ ‏ ‏الْكَاذِبَةُ ‏ ‏مَنْفَقَةٌ ‏ ‏لِلسِّلْعَةِ ‏ ‏مَمْحَقَةٌ ‏ ‏لِلْكَسْبِ ‏","","",""],[8982,8982,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏وَكَانَ يَبْتَدِئُ حَدِيثَهُ بِأَنْ يَقُولَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏الصَّادِقُ الْمَصْدُوقُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[8983,8983,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ حِينَ يَذْكُرُنِي إِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُ وَمَنْ تَقَرَّبَ إِلَيَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا وَمَنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ ‏ ‏بَاعًا ‏ ‏وَمَنْ جَاءَنِي يَمْشِي جِئْتُهُ مُهَرْوِلًا ‏","","",""],[8984,8984,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا أَحَبَّ عَبْدًا دَعَا ‏ ‏جِبْرِيلَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏جِبْرِيلُ ‏ ‏إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ قَالَ فَيُحِبُّهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ إِنَّ اللَّهَ يُحِبُّ فُلَانًا قَالَ فَيُحِبُّهُ أَهْلُ السَّمَاءِ ثُمَّ يُوضَعُ لَهُ الْقَبُولُ فِي الْأَرْضِ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا أَبْغَضَ عَبْدًا دَعَا ‏ ‏جِبْرِيلَ ‏ ‏فَقَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضْهُ قَالَ فَيُبْغِضُهُ ‏ ‏جِبْرِيلُ ‏ ‏ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ إِنَّ اللَّهَ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ قَالَ فَيُبْغِضُهُ أَهْلُ السَّمَاءِ ثُمَّ تُوضَعُ لَهُ الْبَغْضَاءُ فِي الْأَرْضِ ‏","","",""],[8985,8985,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا احْتَذَى النِّعَالَ وَلَا انْتَعَلَ وَلَا رَكِبَ ‏ ‏الْمَطَايَا ‏ ‏وَلَا لَبِسَ ‏ ‏الْكُورَ ‏ ‏مِنْ رَجُلٍ بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ مِنْ ‏ ‏جَعْفَرِ بْنِ أَبِي طَالِبٍ ‏ ‏يَعْنِي فِي ‏ ‏الْجُودِ ‏ ‏وَالْكَرَمِ ‏","","",""],[8986,8986,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ سِيرِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَمَّا أَحَدُهُمَا فَأَلْجَأَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا الْآخَرُ فَأَلْجَأَهُ إِلَى ‏ ‏عُمَرَ ‏ ‏قَالَ أَحَدُهُمَا ‏ ‏نَهَى عَنْ ‏ ‏الزِّقَاقِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَقَالَ الْآخَرُ نَهَى عَنْ ‏ ‏الزِّقَاقِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْجَرِّ ‏ ‏أَوْ الْفَخَّارِ شَكَّ ‏ ‏مُحَمَّدٌ ‏","","",""],[8987,8987,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَجَدَ أَحَدُكُمْ فِي صَلَاتِهِ حَرَكَةً فِي دُبُرِهِ ‏ ‏فَأَشْكَلَ ‏ ‏عَلَيْهِ ‏ ‏أَحْدَثَ ‏ ‏أَوْ لَمْ ‏ ‏يُحْدِثْ ‏ ‏فَلَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[8988,8988,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏وَصَالِحٌ الْمُعَلِّمُ ‏ ‏وَحُمَيْدٌ ‏ ‏وَيُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ مَا اجْتُنِبَتْ الْكَبَائِرُ ‏","","",""],[8989,8989,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[8990,8990,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُخْتَلِعَاتُ ‏ ‏وَالْمُنْتَزِعَاتُ ‏ ‏هُنَّ الْمُنَافِقَاتُ ‏","","",""],[8991,8991,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏الْكِبْرِيَاءُ رِدَائِي وَالْعَظَمَةُ ‏ ‏إِزَارِي ‏ ‏مَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا قَذَفْتُهُ فِي النَّارِ ‏","","",""],[8992,8992,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ أَبِي فَاطَّلَعَ ‏ ‏أَبِي ‏ ‏فِي دَارِ قَوْمٍ فَرَأَى امْرَأَةً فَقَالَ أَمَا إِنَّهُمْ لَوْ فَقَئُوا عَيْنِي لَهُدِرَتْ ثُمَّ قَالَ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اطَّلَعَ فِي دَارِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَفَقَئُوا عَيْنَهُ هُدِرَتْ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً عَيْنٌ ‏","","",""],[8993,8993,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ بِضْعٌ وَسَبْعُونَ بَابًا أَفْضَلُهَا لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏وَأَدْنَاهَا ‏ ‏إِمَاطَةُ ‏ ‏الْعَظْمِ عَنْ الطَّرِيقِ وَالْحَيَاءُ شُعْبَةٌ مِنْ الْإِيمَانِ ‏","","",""],[8994,8994,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[8995,8995,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ رَبَّكُمْ عَزَّ وَجَلَّ يَقُولُ ‏ ‏يَا ابْنَ ‏ ‏آدَمَ ‏ ‏بِكُلِّ حَسَنَةٍ عَشْرُ حَسَنَاتٍ إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ وَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ وَالصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏مِنْ النَّارِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ رِيحِ الْمِسْكِ فَإِنْ جَهِلَ عَلَى أَحَدِكُمْ جَاهِلٌ وَهُوَ صَائِمٌ فَلْيَقُلْ إِنِّي صَائِمٌ ‏","","",""],[8996,8996,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ سَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏ ‏أَوْ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَمَا ظَلَمَ بِأَبِي وَأُمِّي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَآوَوْهُ وَنَصَرُوهُ ‏ ‏قَالَ وَأَحْسَبُهُ قَالَ وَوَاسَوْهُ ‏","","",""],[8997,8997,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا الرَّبِيعِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ فِي أُمَّتِي لَنْ يَدَعُوهَا ‏ ‏التَّطَاعُنُ ‏ ‏فِي الْأَنْسَابِ ‏ ‏وَالنِّيَاحَةُ ‏ ‏وَمُطِرْنَا ‏ ‏بِنَوْءِ ‏ ‏كَذَا وَكَذَا اشْتَرَيْتَ بَعِيرًا أَجْرَبَ ‏ ‏أَوْ فَجَرِبَ ‏ ‏فَجَعَلْتَهُ فِي مِائَةِ بَعِيرٍ فَجَرِبَتْ مَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[8998,8998,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَاسِمُ بْنُ مِهْرَانَ ‏ ‏أَخْبَرَنِيهِ قَالَ سَمِعْتُ ‏ ‏أَبَا رَافِعٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي الْقِبْلَةِ ‏ ‏قَالَ كَانَ يَقُولُ مَرَّةً فَحَتَّهَا ‏ ‏قَالَ ثُمَّ قَالَ قُمْتُ ‏ ‏فَحَتَّيْتُهَا ثُمَّ قَالَ ‏ ‏أَيُحِبُّ أَحَدُكُمْ إِذَا كَانَ فِي صَلَاتِهِ أَنْ ‏ ‏يُتَنَخَّعَ ‏ ‏فِي وَجْهِهِ ‏ ‏أَوْ يُبْزَقَ فِي وَجْهِهِ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاتِهِ فَلَا يَبْزُقَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلَكِنْ عَنْ يَسَارِهِ تَحْتَ قَدَمِهِ فَإِنْ لَمْ يَجِدْ قَالَ بِثَوْبِهِ هَكَذَا ‏","","",""],[8999,8999,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ ‏ ‏يَحْسِرَ ‏ ‏الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ فَيَقْتَتِلَ عَلَيْهِ النَّاسُ حَتَّى يُقْتَلَ مِنْ كُلِّ عَشَرَةٍ تِسْعَةٌ وَيَبْقَى وَاحِدٌ ‏","","",""],[9000,9000,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الصُّبْحِ فَلْيَضْطَجِعْ عَلَى جَنْبِهِ الْأَيْمَنِ ‏","","",""]];
